  }
  return { x: c(p0[0], p1[0], p2[0], p3[0]), y: c(p0[1], p1[1], p2[1], p3[1]) };
}

/* arc-length table */
var NSAMP = 2000, SPTS = [], CUM = [0], ii;
for (ii = 0; ii <= NSAMP; ii++) SPTS.push(crAt(ii / NSAMP * CN));
for (ii = 1; ii <= NSAMP; ii++) CUM.push(CUM[ii - 1] + Math.hypot(SPTS[ii].x - SPTS[ii - 1].x, SPTS[ii].y - SPTS[ii - 1].y));
var TOTALPX = CUM[NSAMP];
var LEN = TOTALPX / 100;           /* wire length in "units" */

function ptAt(t) {
  t = Math.max(0, Math.min(1, t));
  var target = t * TOTALPX, lo = 0, hi = NSAMP, mid;
  while (lo < hi - 1) { mid = (lo + hi) >> 1; if (CUM[mid] <= target) lo = mid; else hi = mid; }
  var seg = CUM[hi] - CUM[lo], f = seg > 1e-9 ? (target - CUM[lo]) / seg : 0;
  return { x: SPTS[lo].x + (SPTS[hi].x - SPTS[lo].x) * f, y: SPTS[lo].y + (SPTS[hi].y - SPTS[lo].y) * f };
}
function tanAt(t) {
  var h = 0.0015, a = ptAt(Math.max(0, t - h)), b = ptAt(Math.min(1, t + h));
  var dx = b.x - a.x, dy = b.y - a.y, l = Math.hypot(dx, dy) || 1;
  return { x: dx / l, y: dy / l };
}
function dens(t) { return 1.15 + 0.85 * Math.sin(3.1 * Math.PI * t + 0.7); }
var EXACT = integrateSimpson(dens, 0, 1, 600) * LEN;

/* self intersection (for the over/under gap) */
function segX(p1, p2, p3, p4) {
  var d = (p2.x - p1.x) * (p4.y - p3.y) - (p2.y - p1.y) * (p4.x - p3.x);
  if (Math.abs(d) < 1e-9) return null;
  var u = ((p3.x - p1.x) * (p4.y - p3.y) - (p3.y - p1.y) * (p4.x - p3.x)) / d;
  var v = ((p3.x - p1.x) * (p2.y - p1.y) - (p3.y - p1.y) * (p2.x - p1.x)) / d;
  if (u < 0 || u > 1 || v < 0 || v > 1) return null;
