    for (b = a + 3; b < idx.length - 1; b++) {
      r = segX(SPTS[idx[a]], SPTS[idx[a + 1]], SPTS[idx[b]], SPTS[idx[b + 1]]);
      if (r) { CROSS = CUM[idx[b]] / TOTALPX; break; }
    }
