})();

/* ===================== state ===================== */
var N = 8, tau = 0.5, sumView = false, K = 6, KC = 0.8, curStep = 0;
(function () {                       /* pick default arc at the loop bottom */
  var best = 1e9, bt = 0.75, i, d;
  for (i = 0; i <= NSAMP; i++) {
    d = Math.hypot(SPTS[i].x - 120, SPTS[i].y - 217.5);
    if (d < best) { best = d; bt = CUM[i] / TOTALPX; }
