})();
function clampK() { return Math.max(1, Math.min(N, Math.floor(KC * N) + 1)); }

/* ===================== groups ===================== */
var gArrow = figDraw.group(), gCurve = figDraw.group(), gHi = figDraw.group(),
  gHit = figDraw.group(), gDots = figDraw.group(), gInset = figDraw.group(),
  gAnn = figDraw.group(), gForm = figDraw.group(), gLab = figDraw.group(),
  gPanel = figDraw.group();

/* ===================== text helper ===================== */
var SVGNS = 'http://www.w3.org/2000/svg';
function mathText(group, x, y, spec, size, anchor, color, halo) {
  var el = document.createElementNS(SVGNS, 'text');
  el.setAttribute('x', x); el.setAttribute('y', y);
  el.setAttribute('text-anchor', anchor || 'middle');
  el.setAttribute('font-family', '"Times New Roman",Times,Georgia,serif');
  el.setAttribute('font-size', size);
  el.setAttribute('fill', color || INK);
  if (halo) {
    el.setAttribute('paint-order', 'stroke');
    el.setAttribute('stroke', '#ffffff');
    el.setAttribute('stroke-width', Math.max(2.4, size * 0.2));
    el.setAttribute('stroke-linejoin', 'round');
  }
  var cur = 0;
  function put(s, off, up) {
    if (!s) return;
    var re = /[A-Za-z]+|[^A-Za-z]+/g, m;
    while ((m = re.exec(s))) {
      var it = !up && /[A-Za-z]/.test(m[0].charAt(0));
      var ts = document.createElementNS(SVGNS, 'tspan');
      ts.textContent = m[0];
      ts.setAttribute('font-size', off === 0 ? size : size * 0.7);
      ts.setAttribute('font-style', it ? 'italic' : 'normal');
      ts.setAttribute('dy', (off - cur).toFixed(2));
      cur = off;
      el.appendChild(ts);
    }
  }
  var i = 0, buf = '', up = false, c, off, s2;
  while (i < spec.length) {
    c = spec.charAt(i);
    if (c === '_' || c === '^') {
      put(buf, 0, up); buf = '';
      off = (c === '_') ? size * 0.30 : -size * 0.42; i++;
      s2 = '';
      if (spec.charAt(i) === '{') { i++; while (i < spec.length && spec.charAt(i) !== '}') { s2 += spec.charAt(i); i++; } i++; }
      else { s2 = spec.charAt(i); i++; }
      put(s2, off, false);
    } else if (c === '#') { put(buf, 0, up); buf = ''; up = true; i++; }
    else if (c === '@') { put(buf, 0, up); buf = ''; up = false; i++; }
    else { buf += c; i++; }
