}

function headAt(g, x, y, dx, dy, size, color) {
  var l = Math.hypot(dx, dy) || 1; dx /= l; dy /= l;
  var px = -dy, py = dx, w = size * 0.45;
  g.polygon([[x, y], [x - dx * size + px * w, y - dy * size + py * w], [x - dx * size - px * w, y - dy * size - py * w]])
    .fill(color).stroke('none');
