  return 'hsl(199,82%,' + (80 - 44 * u).toFixed(1) + '%)';
}

/* ===================== pieces ===================== */
function drawCurve() {
  if (!sumView) {
    gCurve.polyline(curvePts(0, 1, 520)).fill('none')
      .stroke({ color: BLUE, width: 4.5, linecap: 'round', linejoin: 'round' });
  } else {
    var m = 140, i, t0, t1;
    for (i = 0; i < m; i++) {
      t0 = i / m; t1 = Math.min(1, (i + 1) / m + 0.0016);
      gCurve.polyline(curvePts(t0, t1, 5)).fill('none')
        .stroke({ color: densColor(dens((t0 + t1) / 2)), width: 4.8, linecap: 'round' });
    }
  }
  if (CROSS > 0) {
    var w = 14 / TOTALPX;
    gCurve.polyline(curvePts(CROSS - w, CROSS + w, 14)).fill('none')
      .stroke({ color: '#ffffff', width: 12, linecap: 'butt' });
    gCurve.polyline(curvePts(CROSS - w, CROSS + w, 14)).fill('none')
      .stroke({ color: sumView ? densColor(dens(CROSS)) : BLUE, width: 4.8, linecap: 'butt' });
  }
}

function drawHighlight() {
  gHi.polyline(curvePts((K - 1) / N, K / N, 80)).fill('none')
    .stroke({ color: ORANGE, width: 7, linecap: 'round', linejoin: 'round', opacity: 0.85 });
}

function drawHit() {
  var k, pl;
  for (k = 1; k <= N; k++) {
    pl = gHit.polyline(curvePts((k - 1) / N, k / N, 12)).fill('none')
      .stroke({ color: '#000', width: 15, opacity: 0, linecap: 'round' });
    pl.css('cursor', 'pointer');
    (function (kk, el) {
      var ds = LEN / N, f = dens((kk - 1 + tau) / N);
      el.on('mousemove', function (e) {
        showTooltip('Arc ' + kk + ':  Δs = ' + ds.toFixed(3) + ',  f(P*) = ' + f.toFixed(3) +
          ',  ΔM ≈ ' + (f * ds).toFixed(3) + '   (click to zoom this arc)', e);
      }).on('mouseleave', hideTooltip)
        .on('click', function () { K = kk; KC = (K - 0.5) / N; hideTooltip(); render(); });
    })(k, pl);
  }
}

function drawDots() {
  var r = Math.max(1.9, Math.min(5.4, 44 / N)), i, p, c;
  for (i = 0; i <= N; i++) {
    p = ptAt(i / N);
    c = gDots.circle(2 * r).center(p.x, p.y).fill(BLUE).stroke('none');
    if (i === K - 1 || i === K) {
      c.radius(r * 1.45).stroke({ color: ORANGE, width: 1.8 });
    }
    (function (idx, el) {
      el.css('cursor', 'pointer');
      el.on('mousemove', function (e) { showTooltip('Partition point P' + idx + '  (s = ' + (idx / N * LEN).toFixed(2) + ')', e); })
        .on('mouseleave', hideTooltip);
    })(i, c);
  }
  /* red sample point echoed on the wire */
  var ps = ptAt((K - 1 + tau) / N);
  gDots.circle(7).center(ps.x, ps.y).fill(RED).stroke({ color: '#fff', width: 1 });
}

function bez(p0, c1, c2, p3, t) {
  var m = 1 - t;
  return {
    x: m * m * m * p0.x + 3 * m * m * t * c1.x + 3 * m * t * t * c2.x + t * t * t * p3.x,
    y: m * m * m * p0.y + 3 * m * m * t * c1.y + 3 * m * t * t * c2.y + t * t * t * p3.y
