  el.css('cursor', 'pointer');
  el.on('mousemove', function (e) { showTooltip('Zoom: the kth arc, magnified below right', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup('Zooming in on one arc',
        'Over a very short arc the density f barely changes, so the mass of that piece is close to a single density value times the arc length: ΔM\u2096 ≈ f(P*\u2096)Δs\u2096. The inset shows that one arc blown up.');
    });
