  var lx = (ax + bx) / 2 + m.x * 17, ly = (ay + by) / 2 + m.y * 17 + (m.y < 0 ? -2 : size * 0.85);
  mathText(g, lx, ly, label, size, 'middle', INK, true);
}

function drawAnnotations() {
