    var dx = p.x - a.x, dy = p.y - a.y;
    return { x: A.x + dx * ca - dy * sa, y: A.y + dx * sa + dy * ca };
  });
  INSETA = INSET[0];
}

function insetPointAt(u) {
  var M = INSET.length - 1, f = Math.max(0, Math.min(1, u)) * M, i = Math.floor(f);
  if (i >= M) return INSET[M];
  var g = f - i;
  return { x: INSET[i].x + (INSET[i + 1].x - INSET[i].x) * g, y: INSET[i].y + (INSET[i + 1].y - INSET[i].y) * g };
}

function drawInset() {
  buildInset();
  var pts = INSET.map(function (p) { return [p.x, p.y]; });
  var A = INSET[0], B = INSET[INSET.length - 1];
  var grab = gInset.polyline(pts).fill('none').stroke({ color: '#000', width: 20, opacity: 0 });
  gInset.polyline(pts).fill('none').stroke({ color: BLUE, width: 5, linecap: 'round', linejoin: 'round' });
  var dx = B.x - A.x, dy = B.y - A.y, l = Math.hypot(dx, dy) || 1;
  var m = { x: dy / l, y: -dx / l }; if (m.y > 0) { m.x = -m.x; m.y = -m.y; }
  drawBracket(gInset, A, B, m, 'Δs_k', 18, 32);
  gInset.circle(13).center(A.x, A.y).fill(BLUE);
  gInset.circle(13).center(B.x, B.y).fill(BLUE);
  mathText(gLab, A.x - 2, A.y + 26, 'P_{k-1}', 19, 'middle', INK, true);
  mathText(gLab, B.x + 13, B.y + 6, 'P_k', 19, 'start', INK, true);

  var rp = insetPointAt(tau);
  var rd = gInset.circle(12).center(rp.x, rp.y).fill(RED).stroke({ color: '#fff', width: 1.2 });
  rd.css('cursor', 'ew-resize');
  mathText(gLab, 507, 468, 'P^*_k(x^*_k, y^*_k, z^*_k)', 19, 'middle', INK, true);

  function start(e) { dragging = true; hideTooltip(); e.preventDefault(); moveDrag(e); }
  rd.on('mousedown', start); grab.on('mousedown', start);
  rd.on('mousemove', function (e) {
    showTooltip('P*\u2096 — drag me along the arc.  f(P*\u2096) = ' + dens((K - 1 + tau) / N).toFixed(3), e);
  }).on('mouseleave', hideTooltip);
  grab.css('cursor', 'ew-resize');
}

/* ---- formula box (static) ---- */
(function () {
  var r = gForm.rect(273, 48).move(82, 477).fill('#ffffff').stroke({ color: '#9b9b9b', width: 1.6 });
  mathText(gForm, 218, 508, 'ΔM_k ≈ f(x^*_k, y^*_k, z^*_k) Δs_k', 19, 'middle', INK, false);
  r.css('cursor', 'pointer');
  var hit = gForm.rect(273, 48).move(82, 477).fill('#fff').opacity(0);
  hit.css('cursor', 'pointer');
  hit.on('mousemove', function (e) { showTooltip('Mass of one arc ≈ density at a sample point × arc length', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
