/* ---- labels ---- */
function drawLabels() {
  var map = {}, i;
  map[0] = 'P = P_0'; map[N] = 'Q = P_n';
  if (N <= 16) {
    for (i = 1; i <= 3; i++) if (i < N) map[i] = 'P_' + i;
    if (N - 1 > 3) map[N - 1] = 'P_{n-1}';
  }
