  var A = { x: 386, y: 440 }, B = { x: 517, y: 411 };
  var wx = B.x - A.x, wy = B.y - A.y, wlen = Math.hypot(wx, wy);
  var s = Math.min(wlen / vlen, 9);
  var dev = 0, px = -vy / vlen, py = vx / vlen, j, dd;
  for (j = 0; j <= M; j++) { dd = Math.abs((raw[j].x - a.x) * px + (raw[j].y - a.y) * py); if (dd > dev) dev = dd; }
  if (dev * s > 40) s = 40 / dev;
  var ang = Math.atan2(wy, wx) - Math.atan2(vy, vx);
  var ca = Math.cos(ang) * s, sa = Math.sin(ang) * s;
  INSET = raw.map(function (q) {
    var dx = q.x - a.x, dy = q.y - a.y;
    return { x: A.x + dx * ca - dy * sa, y: A.y + dx * sa + dy * ca };
  });
}
function insetPointAt(u) {
  var M = INSET.length - 1, f = Math.max(0, Math.min(1, u)) * M, i = Math.floor(f);
  if (i >= M) return INSET[M];
  var g = f - i;
  return { x: INSET[i].x + (INSET[i + 1].x - INSET[i].x) * g, y: INSET[i].y + (INSET[i + 1].y - INSET[i].y) * g };
}
function drawInset() {
  buildInset();
  var pts = INSET.map(function (p) { return [p.x, p.y]; });
  var A = INSET[0], B = INSET[INSET.length - 1];
  var grab = gInset.polyline(pts).fill('none').stroke({ color: '#000', width: 20, opacity: 0 });
  gInset.polyline(pts).fill('none').stroke({ color: BLUE, width: 5, linecap: 'round', linejoin: 'round' });
  var dx = B.x - A.x, dy = B.y - A.y, l = Math.hypot(dx, dy) || 1;
  var m = { x: dy / l, y: -dx / l }; if (m.y > 0) { m.x = -m.x; m.y = -m.y; }
  drawBracket(gInset, gLab, A, B, m, 'Δs_k', 18, 32, false);
  gInset.circle(13).center(A.x, A.y).fill(BLUE);
  gInset.circle(13).center(B.x, B.y).fill(BLUE);
  mathText(gLab, A.x - 3, A.y + 30, 'P_{k-1}', 19, 'middle', INK, true);
  mathText(gLab, B.x + 14, B.y + 7, 'P_k', 19, 'start', INK, true);
  mathText(gLab, 508, 471, 'P^*_k(x^*_k, y^*_k, z^*_k)', 19, 'middle', INK, true);

  var rp = insetPointAt(tau);
  var rd = gInset.circle(12).center(rp.x, rp.y).fill(RED).stroke({ color: '#fff', width: 1.2 });
  rd.css('cursor', 'ew-resize');
  function start(e) { dragging = true; hideTooltip(); e.preventDefault(); moveDrag(e); }
  rd.on('mousedown', start); grab.on('mousedown', start);
  rd.on('mousemove', function (e) {
    showTooltip('P*\u2096 — drag me along the arc.  f(P*\u2096) = ' + dens((K - 1 + tau) / N).toFixed(3), e);
  }).on('mouseleave', hideTooltip);
  grab.css('cursor', 'ew-resize');
}

/* ===================== formula box (static) ===================== */
(function () {
  var r = gForm.rect(300, 50).move(78, 468).fill('#ffffff').stroke({ color: '#9b9b9b', width: 1.7 });
  mathText(gForm, 228, 500, 'ΔM_k ≈ f(x^*_k, y^*_k, z^*_k) Δs_k', 19, 'middle', INK, false);
  var hit = gForm.rect(300, 50).move(78, 468).fill('#fff').opacity(0);
  hit.css('cursor', 'pointer'); r.css('cursor', 'pointer');
  hit.on('mousemove', function (e) { showTooltip('Mass of one arc ≈ density at a sample point × arc length', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup('ΔM\u2096 ≈ f(x*\u2096, y*\u2096, z*\u2096) Δs\u2096',
        'Each short arc is treated as if it had the constant density measured at one sample point P*\u2096 on it. Multiplying that density by the arc length Δs\u2096 estimates the arc\u2019s mass. Adding these over all k gives a Riemann sum, and as n → ∞ it becomes the line integral ∫_C f ds.');
    });
})();

/* ===================== Riemann panel ===================== */
function riemann() {
  var s = 0, k, ds = LEN / N;
  for (k = 1; k <= N; k++) s += dens((k - 1 + tau) / N) * ds;
  return s;
}
function drawPanel() {
  if (!sumView) return;
  var x0 = 358, y0 = 12, w = 246, h = 198;
  gPanel.rect(w, h).move(x0, y0).radius(5).fill('#ffffff').stroke({ color: '#c9ced4', width: 1.2 }).opacity(0.97);
  mathText(gPanel, x0 + 12, y0 + 21, '#Riemann sum of the @f(P^*_k) #terms', 13, 'start', '#333');
  var bx = x0 + 13, by = y0 + 122, bw = (w - 26) / N, maxH = 78, k, f, hh;
  for (k = 1; k <= N; k++) {
    f = dens((k - 1 + tau) / N);
    hh = Math.max(1.2, f / 2.0 * maxH);
    gPanel.rect(Math.max(1, bw - (N > 30 ? 0.4 : 1.2)), hh)
      .move(bx + (k - 1) * bw, by - hh)
      .fill(k === K ? ORANGE : densColor(f)).stroke('none');
  }
  gPanel.line(bx, by, bx + (w - 26), by).stroke({ color: '#b9bec4', width: 1 });
  var S = riemann(), err = Math.abs(S - EXACT);
  mathText(gPanel, x0 + 13, y0 + 144, 'Σ f(P^*_k)Δs_k = ' + S.toFixed(3), 14, 'start', INK);
  mathText(gPanel, x0 + 13, y0 + 163, '∫_C f ds = ' + EXACT.toFixed(3), 14, 'start', '#1565a8');
  mathText(gPanel, x0 + 13, y0 + 181, '#| error | @= ' + err.toFixed(3), 14, 'start', err < 0.05 ? '#1a7f37' : '#b33');
  mathText(gPanel, x0 + 13, y0 + 194, '#shading: light = small f, deep = large f', 9.5, 'start', '#777');
}

/* ===================== step focus ===================== */
function drawFocus() {
  var i, p, r;
  if (curStep === 1) {
    r = Math.max(2, Math.min(5, 62 / N));
    for (i = 0; i <= N; i++) {
      p = ptAt(i / N);
      gAnn.circle(r * 4.4).center(p.x, p.y).fill('none')
        .stroke({ color: BLUE, width: 1, dasharray: '3,3' }).opacity(0.55);
    }
  } else if (curStep === 2) {
    gAnn.rect(240, 104).move(360, 378).radius(8).fill('none')
      .stroke({ color: ORANGE, width: 1.6, dasharray: '6,5' }).opacity(0.85);
  } else if (curStep === 3) {
    var rp = insetPointAt(tau);
    gAnn.circle(30).center(rp.x, rp.y).fill('none')
      .stroke({ color: RED, width: 1.6, dasharray: '5,4' }).opacity(0.9);
  } else if (curStep >= 4 && sumView) {
    gAnn.rect(252, 204).move(355, 9).radius(7).fill('none')
      .stroke({ color: ORANGE, width: 1.6, dasharray: '6,5' }).opacity(0.75);
  }
}

/* ===================== render ===================== */
function updateReadout() {
  var ds = LEN / N, f = dens((K - 1 + tau) / N), S = riemann();
  var ro = document.getElementById('liveReadout');
  if (ro) {
    ro.innerHTML = 'k = ' + K + ' of ' + N +
      '<br>Δs\u2096 = ' + ds.toFixed(3) +
      '<br>f(P*\u2096) = ' + f.toFixed(3) +
      '<br>ΔM\u2096 ≈ ' + (f * ds).toFixed(3) +
      '<br>Σ = ' + S.toFixed(3) + '   ∫ = ' + EXACT.toFixed(3);
  }
}
function render() {
  K = Math.max(1, Math.min(N, K));
  [gArrow, gCurve, gHi, gHit, gDots, gInset, gAnn, gLab, gPanel].forEach(function (g) { g.clear(); });
  OBS = [];
  pushStaticObs();
  drawZoomArrow();
  drawCurve();
  drawHighlight();
  drawHit();
  drawDots();
  drawInset();
  drawPrimaryLabels();
  drawAnnotations();
  drawSecondaryLabels();
  drawPanel();
  drawFocus();
  updateReadout();
}

/* ===================== interactions ===================== */
function update_numSegments(v) { N = v | 0; K = clampK(); render(); }
function update_sampleParam(v) { tau = +v; render(); }
function toggle_viewMode(on) { sumView = !!on; render(); }

var dragging = false;
function figToLocal(evt) {
  var pt = figDraw.node.createSVGPoint();
  pt.x = evt.clientX; pt.y = evt.clientY;
  var m = figDraw.node.getScreenCTM();
  if (!m) return { x: 0, y: 0 };
  var p = pt.matrixTransform(m.inverse());
  return { x: p.x, y: p.y };
}
function moveDrag(e) {
  var p = figToLocal(e), best = 1e9, bu = tau, i, M = INSET.length - 1, d;
  for (i = 0; i <= M; i++) {
    d = Math.hypot(INSET[i].x - p.x, INSET[i].y - p.y);
    if (d < best) { best = d; bu = i / M; }
  }
  tau = Math.max(0, Math.min(1, bu));
  var inp = document.getElementById('sampleParamInput');
  var out = document.getElementById('sampleParamVal');
  if (inp) inp.value = tau;
  if (out) out.value = tau.toFixed(2);
  render();
}
document.addEventListener('mousemove', function (e) { if (dragging) moveDrag(e); });
document.addEventListener('mouseup', function () { dragging = false; });

/* ===================== demo steps ===================== */
var STEPS = [
  {
    t: 'The curve and its endpoints',
    n: 'A wire follows the space curve C from P = P₀ to Q = Pₙ, with a variable density f(x, y, z) along it. No single density value describes it, so we chop the curve up.',
    s: { n: 14, tau: 0.5, sum: false }
  },
  {
    t: 'Partition into n arcs',
    n: 'Partition points P₀, P₁, …, Pₙ split C into n arcs (shown ringed). The kth arc has length Δsₖ and carries an unknown mass ΔMₖ.',
    s: { n: 8, tau: 0.5, sum: false }
  },
  {
    t: 'Zoom in on the kth arc',
    n: 'Zooming into the arc from P_{k−1} to P_k, pick any sample point P*ₖ(x*ₖ, y*ₖ, z*ₖ) on it. Over such a short arc the density is nearly constant, so ΔMₖ ≈ f(x*ₖ, y*ₖ, z*ₖ)Δsₖ.',
    s: { n: 8, tau: 0.5, sum: false }
  },
  {
    t: 'The choice of P*ₖ barely matters',
    n: 'Slide or drag the red dot to either end of the arc. The estimate of ΔMₖ shifts a little, but every choice is a valid approximation — and the spread shrinks with the arc.',
    s: { n: 8, tau: 0.05, sum: false }
  },
  {
    t: 'Add up all the arcs',
    n: 'Summing f(P*ₖ)Δsₖ over all k gives a Riemann sum that approximates the total mass of the wire.',
    s: { n: 8, tau: 0.5, sum: true }
  },
  {
    t: 'Let n → ∞',
    n: 'Push n up: the arcs shrink, the sample-point ambiguity disappears, and the Riemann sum locks onto the exact value ∫_C f(x, y, z) ds.',
    s: { n: 60, tau: 0.5, sum: true }
  }
];

function applyStep(i) {
  curStep = (i + STEPS.length) % STEPS.length;
  var st = STEPS[curStep].s;
  N = st.n; tau = st.tau; sumView = st.sum; K = clampK();
  var a = document.getElementById('numSegmentsInput'); if (a) a.value = N;
  var b = document.getElementById('numSegmentsVal'); if (b) b.value = N;
  var c = document.getElementById('sampleParamInput'); if (c) c.value = tau;
  var d = document.getElementById('sampleParamVal'); if (d) d.value = tau.toFixed(2);
  var e = document.getElementById('viewModeInput'); if (e) e.checked = sumView;
  var nn = document.getElementById('demoNarration');
  if (nn) nn.innerHTML = '<b>' + STEPS[curStep].t + '</b><br>' + STEPS[curStep].n;
  var sl = document.getElementById('stepLabel');
  if (sl) sl.textContent = 'Step ' + (curStep + 1) + ' / ' + STEPS.length;
  render();
}
function nextStep() { applyStep(curStep + 1); }
function prevStep() { applyStep(curStep - 1); }

/* ===================== init ===================== */
applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

