// @FIGURE_CODE_BEGIN
/* ===================== setup ===================== */
var VW = 620, VH = 535;
var figDraw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
figDraw.viewbox(0, 0, VW, VH);

var BLUE = '#22a0dd', DEEPBLUE = '#0d6ea8', ORANGE = '#ef8a1e', RED = '#e8332a',
  CREAM = '#fbe5c0', GRAYO = '#a3a3a3', INK = '#121212';

/* control points of the wire (screen units, y down) */
var CPTS = [[21, 443], [58, 415], [95, 386], [148.5, 341.5], [180, 310], [202.5, 276],
[217.5, 235], [221.5, 195], [218.5, 157.5], [205, 122.5], [172.5, 103.5], [140, 99],
[102.5, 111], [79, 140], [75, 172.5], [89, 200], [120, 217.5], [150, 214], [176, 202.5],
[200, 187.5], [225, 165], [248.5, 131], [270, 84], [282.5, 34]];
var CN = CPTS.length - 1;

function crAt(u) {
  var i = Math.floor(u); if (i > CN - 1) i = CN - 1; if (i < 0) i = 0;
  var t = u - i;
  var p0 = CPTS[Math.max(0, i - 1)], p1 = CPTS[i], p2 = CPTS[i + 1], p3 = CPTS[Math.min(CPTS.length - 1, i + 2)];
  var t2 = t * t, t3 = t2 * t;
  function c(a, b, cc, d) {
    return 0.5 * ((2 * b) + (-a + cc) * t + (2 * a - 5 * b + 4 * cc - d) * t2 + (-a + 3 * b - 3 * cc + d) * t3);
  }
  return { x: c(p0[0], p1[0], p2[0], p3[0]), y: c(p0[1], p1[1], p2[1], p3[1]) };
}

/* arc-length table */
var NSAMP = 2000, SPTS = [], CUM = [0], ii;
for (ii = 0; ii <= NSAMP; ii++) SPTS.push(crAt(ii / NSAMP * CN));
for (ii = 1; ii <= NSAMP; ii++) CUM.push(CUM[ii - 1] + Math.hypot(SPTS[ii].x - SPTS[ii - 1].x, SPTS[ii].y - SPTS[ii - 1].y));
var TOTALPX = CUM[NSAMP];
var LEN = TOTALPX / 100;

function ptAt(t) {
