    drawBracket(gAnn, gLab, s.A, s.B, s.m, 'Δs_k', 17, 30, true);
  }
  /* Mass ΔM_k leader */
  var p = ptAt(Math.max(0, (K - 0.55) / N)), mo = s.mo;
  var T = { x: p.x + mo.x * 8, y: p.y + mo.y * 8 };
  var cands = [
    [mo.x * 54 - 34, mo.y * 54 + 18], [mo.x * 62 - 8, mo.y * 62 + 24],
    [mo.x * 72 + 24, mo.y * 72 + 12], [-66, 50], [66, 52], [-72, -28], [0, 78]
  ];
  var r = placeText(gLab, T.x, T.y, '#Mass @ΔM_k', 16, cands, INK);
  var sx = r.cx + (T.x > r.cx ? r.box.w / 2 + 3 : -r.box.w / 2 - 3), sy = r.cy - 1;
  var cx = (sx + T.x) / 2 + (T.y - sy) * 0.2, cy = (sy + T.y) / 2 + (sx - T.x) * 0.2;
  gAnn.path('M' + sx + ',' + sy + ' Q' + cx + ',' + cy + ' ' + T.x + ',' + T.y)
    .fill('none').stroke({ color: INK, width: 1.3 });
  headAt(gAnn, T.x, T.y, T.x - cx, T.y - cy, 7.5, INK);
  segObs(sx, sy, T.x, T.y, 5);
}

/* ===================== secondary labels ===================== */
function labelAtIndex(idx, spec, size) {
