/* ===================== inset ===================== */
var INSET = [];
function buildInset() {
  var t0 = (K - 1) / N, t1 = K / N, M = 48, raw = [], i;
  for (i = 0; i <= M; i++) raw.push(ptAt(t0 + (t1 - t0) * i / M));
  var a = raw[0], b = raw[M];
  var vx = b.x - a.x, vy = b.y - a.y, vlen = Math.hypot(vx, vy) || 0.001;
  var A = IA, B = IB;
  var wx = B.x - A.x, wy = B.y - A.y, wlen = Math.hypot(wx, wy);
  var s = Math.min(wlen / vlen, 10);
  var dev = 0, px = -vy / vlen, py = vx / vlen, j, dd;
  for (j = 0; j <= M; j++) { dd = Math.abs((raw[j].x - a.x) * px + (raw[j].y - a.y) * py); if (dd > dev) dev = dd; }
  if (dev * s > 42) s = 42 / dev;
  var ang = Math.atan2(wy, wx) - Math.atan2(vy, vx);
  var ca = Math.cos(ang) * s, sa = Math.sin(ang) * s;
  INSET = raw.map(function (q) {
    var dx = q.x - a.x, dy = q.y - a.y;
    return { x: A.x + dx * ca - dy * sa, y: A.y + dx * sa + dy * ca };
  });
}
function insetPointAt(u) {
  var M = INSET.length - 1, f = Math.max(0, Math.min(1, u)) * M, i = Math.floor(f);
  if (i >= M) return INSET[M];
  var g = f - i;
  return { x: INSET[i].x + (INSET[i + 1].x - INSET[i].x) * g, y: INSET[i].y + (INSET[i + 1].y - INSET[i].y) * g };
}
function drawInset() {
  var pts = INSET.map(function (p) { return [p.x, p.y]; });
  var A = INSET[0], B = INSET[INSET.length - 1];
  var grab = gInset.polyline(pts).fill('none').stroke({ color: '#000', width: 22, opacity: 0 });
  gInset.polyline(pts).fill('none').stroke({ color: BLUE, width: 5.4, linecap: 'round', linejoin: 'round' });
  var dx = B.x - A.x, dy = B.y - A.y, l = Math.hypot(dx, dy) || 1;
  var m = { x: dy / l, y: -dx / l }; if (m.y > 0) { m.x = -m.x; m.y = -m.y; }
  drawBracket(gInset, gLab, A, B, m, 'Δs_k', 20, 36, false);
  gInset.circle(14).center(A.x, A.y).fill(BLUE);
  gInset.circle(14).center(B.x, B.y).fill(BLUE);
  mathText(gLab, LBL_PK1.x, LBL_PK1.y + ILS * 0.35, 'P_{k-1}', ILS, 'middle', INK, true);
  mathText(gLab, LBL_PK.x, LBL_PK.y, 'P_k', ILS, 'start', INK, true);
  mathText(gLab, LBL_PSTAR.x, LBL_PSTAR.y + ILS * 0.35, 'P^*_k(x^*_k, y^*_k, z^*_k)', ILS, 'middle', INK, true);

  var rp = insetPointAt(tau);
  var rd = gInset.circle(13).center(rp.x, rp.y).fill(RED).stroke({ color: '#fff', width: 1.2 });
  rd.css('cursor', 'ew-resize');
  function start(e) { dragging = true; engaged = true; hideTooltip(); e.preventDefault(); moveDrag(e); }
  rd.on('mousedown', start); grab.on('mousedown', start);
  rd.on('mousemove', function (e) {
    showTooltip('P*\u2096 — drag me along the arc.  f(P*\u2096) = ' + dens((K - 1 + tau) / N).toFixed(3), e);
  }).on('mouseleave', hideTooltip);
  grab.css('cursor', 'ew-resize');
}

/* ===================== formula box (static) ===================== */
(function () {
  var r = gForm.rect(BOX.w, BOX.h).move(BOX.x, BOX.y).fill('#ffffff').stroke({ color: '#9b9b9b', width: 1.7 });
  mathText(gForm, BOX.x + BOX.w / 2, BOX.y + BOX.h / 2 + 7,
