        'Each short arc is treated as if it had the constant density measured at one sample point P*\u2096 on it. Multiplying that density by the arc length Δs\u2096 estimates the arc\u2019s mass. Adding these over all k gives a Riemann sum, and as n → ∞ it becomes the line integral ∫_C f ds.');
    });
})();

/* ===================== Riemann panel ===================== */
function riemann() {
  var s = 0, k, ds = LEN / N;
  for (k = 1; k <= N; k++) s += dens((k - 1 + tau) / N) * ds;
  return s;
}
function drawPanel() {
  if (!sumView) return;
  var x0 = 358, y0 = 12, w = 246, h = 198;
  gPanel.rect(w, h).move(x0, y0).radius(5).fill('#ffffff').stroke({ color: '#c9ced4', width: 1.2 }).opacity(0.97);
  mathText(gPanel, x0 + 12, y0 + 21, '#Riemann sum of the @f(P^*_k) #terms', 13, 'start', '#333');
  var bx = x0 + 13, by = y0 + 122, bw = (w - 26) / N, maxH = 78, k, f, hh;
  for (k = 1; k <= N; k++) {
    f = dens((k - 1 + tau) / N);
    hh = Math.max(1.2, f / 2.0 * maxH);
    gPanel.rect(Math.max(1, bw - (N > 30 ? 0.4 : 1.2)), hh)
      .move(bx + (k - 1) * bw, by - hh)
      .fill(k === K ? hlCol() : densColor(f)).stroke('none');
  }
  gPanel.line(bx, by, bx + (w - 26), by).stroke({ color: '#b9bec4', width: 1 });
  var S = riemann(), err = Math.abs(S - EXACT);
  mathText(gPanel, x0 + 13, y0 + 144, 'Σ f(P^*_k)Δs_k = ' + S.toFixed(3), 14, 'start', INK);
  mathText(gPanel, x0 + 13, y0 + 163, '∫_C f ds = ' + EXACT.toFixed(3), 14, 'start', '#1565a8');
  mathText(gPanel, x0 + 13, y0 + 181, '#| error | @= ' + err.toFixed(3), 14, 'start', err < 0.05 ? '#1a7f37' : '#b33');
  mathText(gPanel, x0 + 13, y0 + 194, '#shading: light = small f, deep = large f', 9.5, 'start', '#777');
}

/* ===================== step focus ===================== */
function drawFocus() {
  var i, p, r;
  if (curStep === 1) {
    r = Math.max(2, Math.min(5, 62 / N));
    for (i = 0; i <= N; i++) {
      p = ptAt(i / N);
      gAnn.circle(r * 4.4).center(p.x, p.y).fill('none')
        .stroke({ color: BLUE, width: 1, dasharray: '3,3' }).opacity(0.55);
    }
  } else if (curStep === 2) {
    gAnn.rect(250, 124).move(366, 364).radius(8).fill('none')
      .stroke({ color: DEEPBLUE, width: 1.5, dasharray: '6,5' }).opacity(0.7);
  } else if (curStep === 3) {
    var rp = insetPointAt(tau);
    gAnn.circle(32).center(rp.x, rp.y).fill('none')
      .stroke({ color: RED, width: 1.6, dasharray: '5,4' }).opacity(0.9);
  } else if (curStep >= 4 && sumView) {
    gAnn.rect(252, 204).move(355, 9).radius(7).fill('none')
      .stroke({ color: DEEPBLUE, width: 1.5, dasharray: '6,5' }).opacity(0.7);
  }
}

/* ===================== render ===================== */
function updateReadout() {
  var ds = LEN / N, f = dens((K - 1 + tau) / N), S = riemann();
  var ro = document.getElementById('liveReadout');
  if (ro) {
    ro.innerHTML = 'k = ' + K + ' of ' + N +
      '<br>Δs\u2096 = ' + ds.toFixed(3) +
      '<br>f(P*\u2096) = ' + f.toFixed(3) +
      '<br>ΔM\u2096 ≈ ' + (f * ds).toFixed(3) +
      '<br>Σ = ' + S.toFixed(3) + '   ∫ = ' + EXACT.toFixed(3);
  }
}
function render() {
  K = Math.max(1, Math.min(N, K));
  [gArrow, gCurve, gHi, gHit, gDots, gInset, gAnn, gLab, gPanel].forEach(function (g) { g.clear(); });
  OBS = [];
  buildInset();
  pushStaticObs();
  drawZoomArrow();
  drawCurve();
  drawHighlight();
  drawHit();
  drawDots();
  drawInset();
  drawPrimaryLabels();
  drawAnnotations();
  drawSecondaryLabels();
  drawPanel();
  drawFocus();
  updateReadout();
}

/* ===================== interactions ===================== */
function update_numSegments(v) { engaged = true; N = v | 0; K = clampK(); render(); }
function update_sampleParam(v) { engaged = true; tau = +v; render(); }
function toggle_viewMode(on) { engaged = true; sumView = !!on; render(); }

var dragging = false;
function figToLocal(evt) {
  var pt = figDraw.node.createSVGPoint();
  pt.x = evt.clientX; pt.y = evt.clientY;
  var m = figDraw.node.getScreenCTM();
  if (!m) return { x: 0, y: 0 };
  var p = pt.matrixTransform(m.inverse());
  return { x: p.x, y: p.y };
}
function moveDrag(e) {
  var p = figToLocal(e), best = 1e9, bu = tau, i, M = INSET.length - 1, d;
  for (i = 0; i <= M; i++) {
    d = Math.hypot(INSET[i].x - p.x, INSET[i].y - p.y);
    if (d < best) { best = d; bu = i / M; }
  }
  tau = Math.max(0, Math.min(1, bu));
  var inp = document.getElementById('sampleParamInput');
  var out = document.getElementById('sampleParamVal');
  if (inp) inp.value = tau;
  if (out) out.value = tau.toFixed(2);
  render();
}
document.addEventListener('mousemove', function (e) { if (dragging) moveDrag(e); });
document.addEventListener('mouseup', function () { dragging = false; });

